import { utf8Encode } from './encoding.mjs';
import { encryptBlock } from './aes/block_cipher.mjs';
import { expandKey } from './aes/key_schedule.mjs';

export class AesModeOfOperationECB {
  constructor(keyBytes) {
    this.expandedKey = expandKey(keyBytes);
  }

  encrypt(blockBytes) {
    return encryptBlock(blockBytes, this.expandedKey);
  }
}

export function encryptUtf8Blocks(keyText, dataText) {
  const aes = new AesModeOfOperationECB(utf8Encode(keyText));
  const dataBytes = utf8Encode(dataText);
  const ciphertexts = [];

  for (let offset = 0; offset < dataBytes.length; offset += 16) {
    const block = dataBytes.subarray(offset, offset + 16);
    ciphertexts.push(aes.encrypt(block));
  }

  return ciphertexts;
}

