function escapeByte(byte, quote) {
  if (byte === 0x5c) {
    return '\\\\';
  }

  if (byte === 0x09) {
    return '\\t';
  }

  if (byte === 0x0a) {
    return '\\n';
  }

  if (byte === 0x0d) {
    return '\\r';
  }

  if (byte === quote.charCodeAt(0)) {
    return `\\${quote}`;
  }

  if (byte >= 0x20 && byte <= 0x7e) {
    return String.fromCharCode(byte);
  }

  return `\\x${byte.toString(16).padStart(2, '0')}`;
}

export function bytesToPythonRepr(bytes) {
  const quote = chooseQuote(bytes);
  let output = `b${quote}`;

  for (const byte of bytes) {
    output += escapeByte(byte, quote);
  }

  output += quote;
